INSERT INTO `campuses` (`id`, `university_id`, `campus_admin_uid`, `verification_id`, `name`, `campus_type`, `city`, `province`, `address`, `description`, `why_choose`, `phone`, `whatsapp`, `email`, `office_hours`, `shift_morning`, `shift_evening`, `shift_weekend`, `gender_policy`, `lat`, `lng`, `hostel_available`, `is_main`, `admission_open`, `admission_close`, `intake_name`, `classes_start`, `class_arrangement`, `admission_status_override`, `students`, `status`, `cover_image`, `created_at`, `updated_at`, `required_documents`, `scholarships`, `quota_policy`, `announcements`) VALUES
('1bc3b963-a9a3-573b-85f5-2a3e6226175d', 'af8ed5c5-abfd-4f9e-aa8c-f1c6b55e71ce', '85f5554a-b4f3-4219-a37c-69ed991821bf', 'cr_1bc3b963a9a3573b85', 'The Superior University, Lahore – Gold Campus', 'City Campus', 'Lahore', 'Punjab', '6 KM, Main Raiwind Road, Lahore, Punjab', 'Gold Campus houses Computer Science and Information Technology programs, with laboratories and HEC-aligned curriculum.', 'Dedicated CS/IT campus with labs and HEC-approved curriculum.', '042-38102223', NULL, NULL, 'Mon–Fri 08:00 AM – 4:00 PM', 1, 0, 0, 'Co-Education', 31.41903120, 74.23030810, 0, 0, NULL, NULL, 'Fall 2026', NULL, 'On-Campus', 'open', NULL, 'active', NULL, '2026-10-29 12:30:00', '2026-10-29 12:30:00', NULL, NULL, NULL, NULL),
('1c3f1081-1e59-4579-955a-22e3509eb4a9', '4017d40c-d81a-4fc4-b8d8-6e88ffa08c4b', 'b64c59f1-3f5d-4905-a5df-7ce513a56b7c', 'cr_17933741421965611', 'RIU, QIE Lahore', 'Regional Campus', 'Lahore', 'Punjab', 'qie lahore campus', 'Riphah International University\'s QIE Campus is located at 28-M, Quaid-e-Azam Industrial Estate, Kot Lakhpat, Lahore. The campus is home to the Riphah School of Computing & Innovation (RSCI), operating under the Faculty of Computing.\n\nThe campus offers undergraduate degree programs in Computer Science, Software Engineering, Artificial Intelligence, Cyber Security, Data Science, Information Technology, and Computer Graphics & Visualization.\n\nQIE Campus focuses on quality computing education, innovation, practical skill development, and academic excellence. Its academic programs aim to equip students with technical knowledge, analytical abilities, and problem-solving skills relevant to the evolving technology industry.', '- **Specialized Computing Education:** Home to the Riphah School of Computing & Innovation (RSCI), dedicated to computing and emerging technologies.\n\n- **Diverse Technology Programs:** Offers undergraduate degrees in Computer Science, Software Engineering, Artificial Intelligence, Cyber Security, Data Science, Information Technology, and Computer Graphics & Visualization.\n\n- **Industry-Relevant Learning:** Emphasizes practical skills, technical knowledge, innovation, and problem-solving abilities.\n\n- **Academic Quality:** Programs operate under Riphah\'s Faculty of Computing, which emphasizes academic standards and curriculum quality.\n\n- **Innovation and Research:** Encourages students to develop creative thinking, technical expertise, and research-oriented approaches to real-world challenges.\n\n- **Convenient Lahore Location:** Situated in Quaid-e-Azam Industrial Estate, Kot Lakhpat, Lahore.\n\n- **Professional Development:** Focuses on preparing graduates with technical, analytical, and entrepreneurial capabilities for future careers in technology.', '+923434322455', '', 'qielahore@riphah.edu.pk', 'Mon-Fri, 9:00 AM - 5:00PM', 1, 0, 0, 'co-education', 31.45462880, 74.32516020, 1, 0, NULL, NULL, 'Fall 2026', NULL, 'mixed', 'open', '1000', 'active', NULL, '2026-10-30 20:36:32', '2026-10-31 11:27:53', NULL, NULL, NULL, NULL),
('21d2f072-fe52-409f-8e47-d81f9a9d678d', '602cc750-7a7e-4151-8525-a0680dcab56b', '2aacfe39-a0b6-4d0c-a5c0-365ba01c8392', 'cr_17925882409474473', 'The University of Lahore – Uganda Campus', 'International Campus', 'Kampala', 'Wakiso District', 'Kampala, Uganda', 'UOL\'s international campus in Uganda, established through technical support for the Habib Medical School at the Islamic University in Uganda (IUIU). This partnership extends UOL\'s educational reach globally.', NULL, NULL, NULL, NULL, NULL, 1, 0, 0, 'Coeducational', 0.31630000, 32.29190000, 0, 0, NULL, NULL, 'Fall 2026', NULL, NULL, NULL, NULL, 'active', 'https://uol.edu.pk/wp-content/uploads/2025/05/DSC09875.jpg', '2026-10-21 18:12:43', '2026-10-22 09:29:45', NULL, '[{\"name\":\"Merit-Based Scholarship\",\"type\":\"Internal\",\"coverage\":\"Up to 100% tuition fee waiver for high-achieving students.\",\"criteria\":\"Awarded to top position holders in FSc/A-Level or equivalent, renewable on CGPA >= 3.5.\"},{\"name\":\"Need-Based Financial Aid\",\"type\":\"Internal\",\"coverage\":\"25%-75% tuition fee waiver based on financial need.\",\"criteria\":\"Family income below PKR 1,200,000/year. Apply via Financial Assistance Office (Ext: 4116) after depositing minimum 50% tuition fee.\"},{\"name\":\"Scholarship for Students with Disabilities\",\"type\":\"Internal\",\"coverage\":\"Up to 100% tuition fee waiver.\",\"criteria\":\"Valid disability certificate from a recognised medical board.\"},{\"name\":\"International Student Grant\",\"type\":\"Internal\",\"coverage\":\"10%-25% tuition fee concession for international students.\",\"criteria\":\"Available for students from Gulf, South/Central Asia, Africa, Europe, and North America based on academic merit.\"},{\"name\":\"Alumni Scholarship\",\"type\":\"Internal\",\"coverage\":\"10%-15% tuition fee waiver for children/siblings of UOL alumni.\",\"criteria\":\"Verified alumni relationship certificate required.\"},{\"name\":\"Kinship-Based Assistance\",\"type\":\"Internal\",\"coverage\":\"10% tuition fee concession for siblings studying concurrently at UOL.\",\"criteria\":\"Both siblings must be active students; renewable each semester.\"},{\"name\":\"HEC Need-cum-Merit Scholarship\",\"type\":\"External\",\"coverage\":\"Tuition fee + monthly stipend.\",\"criteria\":\"Family income verified by HEC; CGPA >= 2.5 maintained.\"},{\"name\":\"PEEF Scholarship (Punjab Educational Endowment Fund)\",\"type\":\"External\",\"coverage\":\"Full tuition fee.\",\"criteria\":\"Domicile of Punjab; family income below PKR 45,000/month; CGPA >= 2.0.\"}]', NULL, NULL),
('21fea945-1184-4e3a-86bc-d522cc985bd5', 'bdbf8537-15f0-46fa-b5e8-6eb2680fc0f8', '7de3adbe-0304-4aa8-98ed-c39f59b9b6ef', 'cr_17925320568732685', 'Chiniot-Faisalabad', 'Sub-Campus', 'Chiniot-Faisalabad', 'Punjab', 'Loonaywala Stop (9 Km from Motorway Interchange), Faisalabad-Chiniot Road', 'The 5th campus of FAST-NU in the middle of Chiniot-Faisalabad. It has the honor of being Pakistan\'s first federal chartered multi-campus university.\n\nHostels: Separate hostel accommodation is available for both male and female students.', 'State-of-the-art computing facilities, well-equipped labs, lush green playgrounds, and highly conducive environment for learning and development.', '+92-41-111-128-128', NULL, 'admissions.cfd@nu.edu.pk', 'Mon-Fri 8:00-17:00', 1, 0, 0, 'Co-Education', 31.55020000, 72.98410000, 1, 0, '2026-05-20', '2026-06-30', 'Fall 2026', '2026-08-17', 'On-Campus', NULL, NULL, 'active', NULL, '2026-10-21 02:36:44', '2026-10-21 02:58:17', NULL, NULL, NULL, NULL),
('2e979544-a811-5988-90bf-84247dc93a0e', 'af8ed5c5-abfd-4f9e-aa8c-f1c6b55e71ce', '85f5554a-b4f3-4219-a37c-69ed991821bf', 'cr_2e979544a811598890', 'The Superior University, Lahore – RAK Campus', 'Sub-Campus', 'Ras Al Khaimah', '', '5th Floor, Tower 2, RAKEZ Service Centre, Amenity Centre, Al Jazeera Al Hamra, Ras Al Khaimah, UAE', 'Located in the Academic Zone of Ras Al Khaimah Economic Zone (RAKEZ). Uses blended learning combining classroom teaching with online resources. Not in Dubai.', 'International RAKEZ campus with blended learning and IWEP bootcamp.', NULL, NULL, 'internationaloffice@superior.edu.pk', NULL, 1, 0, 0, 'Co-Education', NULL, NULL, 0, 0, NULL, NULL, 'Fall 2026', NULL, 'Hybrid', 'open', NULL, 'active', NULL, '2026-10-29 12:30:00', '2026-10-29 12:30:00', NULL, NULL, NULL, NULL),
('31215899-3bde-56ea-8bc3-74c55f2d282c', 'af8ed5c5-abfd-4f9e-aa8c-f1c6b55e71ce', '85f5554a-b4f3-4219-a37c-69ed991821bf', 'cr_312158993bde56ea8b', 'The Superior University, Lahore – Layyah Campus', 'Sub-Campus', 'Layyah', 'Punjab', 'Canal Road Karor Near Sugar Mill, Layyah', 'Established to expand access in Southern Punjab. Classrooms, computer and teaching labs, and a library. Undergraduate and postgraduate programs with 3U1M.', 'HEC-recognized sub-campus serving southern Punjab.', '0321-8768880', '0340-1455555', NULL, 'Mon–Fri 08:00 AM – 4:00 PM', 1, 0, 0, 'Co-Education', NULL, NULL, 0, 0, NULL, NULL, 'Fall 2026', NULL, 'On-Campus', 'open', NULL, 'active', NULL, '2026-10-29 12:30:00', '2026-10-29 12:30:00', NULL, NULL, NULL, NULL),
('45ea2aca-b42d-44f6-996e-808da82b576a', '4017d40c-d81a-4fc4-b8d8-6e88ffa08c4b', 'ea779f4b-7616-4515-a29b-eea7b1753bdc', 'cr_17933740110273180', 'Riphah International University, Raiwind Campus', 'Regional Campus', 'Lahore', 'Punjab', 'raiwind campus near ada plot', 'Riphah campus situated along Raiwind Road, Lahore, offering a mix of disciplines. Campus Director: Dr. Sheheryar Malik.', '', '+923422344554', '+923000723192', 'raiwindcampus@riphah.edu.pk', '9:00 AM-5:00 PM', 1, 0, 0, 'co-education', 0.00000000, 0.00000000, 1, 0, NULL, NULL, '', NULL, 'mixed', 'closed', '1000', 'active', NULL, '2026-10-30 20:36:37', '2026-10-31 11:27:52', NULL, NULL, NULL, NULL),
('4717a5f7-ffcf-40d8-9eff-7baa8d9d63a8', 'bbfed128-41b9-40c5-a22c-9b6ce3081a3f', '819551da-ec91-4067-a753-fa369ba55800', 'cr_1791964766582416', 'University of Central Punjab – Lahore Campus', 'Main Campus', 'Lahore', 'Punjab', '1 Khayaban-e-Jinnah Road, Johar Town, Lahore, Pakistan', 'UCP\'s principal campus in Johar Town, Lahore, home to all nine faculties. It houses engineering, IT, pharmacy and science laboratories, a media hub with a production house and 24/7 FM radio, a sports complex with a swimming pool, a 400-seat auditorium and a library of about 40,000 textbooks.', 'All nine faculties on a single Lahore campus, scholarships for a large share of students (PKR 1.3B awarded, 37% of students on financial aid), in-house media hub and FM 92.6 radio, solar-powered campus and a shuttle service on 8 city routes.', '+923235880007', '', 'info@ucp.edu.pk', '9:00 AM – 5:00 PM', 1, 0, 1, 'co-education', 31.44690000, 74.26820000, 1, 0, '2026-06-01', '2026-09-15', 'Fall 2026', '2026-09-28', '', 'closed', '16600', 'active', NULL, '2026-10-14 13:00:54', '2026-10-14 14:42:15', '[]', '[]', '', '[]'),
