INSERT INTO `universities` (`id`, `owner_uid`, `name`, `normalized_name`, `hec_rank`, `university_type`, `oric_domain`, `focal_person_name`, `focal_person_email`, `campuses_text`, `campus_count`, `last_synced_at`, `description`, `website`, `email`, `phone`, `city`, `address`, `established_year`, `logo_url`, `banner_url`, `tagline`, `hero_subtitle`, `about_title`, `about_text`, `mission`, `vision`, `ranking`, `ranking_label`, `students`, `employment_rate`, `partner_countries`, `total_campuses`, `domain`, `campuses`, `is_hec_listed`, `created_at`, `updated_at`, `province`, `status`) VALUES
('f3f5dbc5-cf02-451a-86e1-d468921720f0', '0f92ecb1-98c7-49fa-beeb-d00f78b39aaf', 'COMSATS University Islamabad', 'comsats university islamabad', 7, 'Public', '@comsats.edu.pk', 'Mr. Attiq Rehman', 'attiq_rehman@comsats.edu.pk', 'Islamabad (Main Campus); Sahiwal Campus; Attock Campus; Abbottabad Campus; Vehari Campus; Lahore Campus; Wah Campus', 7, '2026-11-09 17:04:46', NULL, 'https://www.comsats.edu.pk', 'admissions@comsats.edu.pk', '+92-51-90495032', 'Islamabad', 'Park Road, Tarlai Kalan, Islamabad, 45550, Pakistan', '1998', 'https://www.comsats.edu.pk/assets/img/COMSATS-logo.png', 'https://www.comsats.edu.pk/assets/img/all-campuses.jpg', 'Excellence in Higher Education, Innovative Research and Service to Society', 'Chartered public research university by the Federal Government of Pakistan with 7 physical campuses and a Virtual Campus (NOC pending with HEC) nationwide', 'About COMSATS University Islamabad', 'COMSATS University Islamabad (CUI) is a public sector university chartered by the Federal Government of Pakistan in 2018 (originally established as CIIT in 1998). CUI functions under the governance of the Ministry of Science and Technology. The university comprises 7 physical campuses - Islamabad (Main Campus), Lahore, Abbottabad, Wah Cantt, Attock, Sahiwal, and Vehari - plus a Virtual Campus that is currently not operational and is seeking HEC NOC to launch distance learning programs. It hosts 6 faculties, 23 academic departments, 6 research centers, and over 39,000 enrolled students. CUI has consistently ranked among top national universities and leading international institutions according to Times Higher Education (THE) and QS World University Rankings.', 'The COMSATS University Islamabad, founded in the belief that understanding enriches all people, is dedicated to the search for truth through advancement of learning and extending the frontiers of knowledge; to the sharing of this knowledge through education in an academically diverse range of disciplines and subjects; and to the application of this knowledge to benefit the people of Pakistan, the Muslim Ummah, and the World, at large.', 'The COMSATS University Islamabad envisions assuming a truly national character for itself in the years to come. It envisions having presence in all provinces of the country. It sees for itself a position among the top five universities in the country; among top 100 universities in the developing countries and top 300, 200, 100 universities in the world respectively in the 5, 10 and 15-years\' time horizon.', '1', '#1 in Pakistan (THE Impact Rankings 2024)', '39,100+', '88%', '35+', '7', 'comsats.edu.pk', 'Islamabad (Main Campus); Sahiwal Campus; Attock Campus; Abbottabad Campus; Vehari Campus; Lahore Campus; Wah Campus', 1, '2026-10-14 10:39:52', '2026-11-09 17:04:46', NULL, 'approved'),
('f4ea07a5-f509-408a-9b79-7d5453d77fd4', NULL, 'Aror University of Art, Architecture, Design and Heritage, Sukkur', 'aror university of art architecture design and heritage sukkur', 214, 'Public', NULL, 'Mr. Ayaz Ahmed', 'pqr@aror.edu.pk', 'Sukkur (Main Campus)', 1, '2026-11-09 17:04:46', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', NULL, 'Sukkur (Main Campus)', 1, '2026-10-14 10:39:53', '2026-11-09 17:04:46', NULL, 'pending'),
